-- mod-atlas: clone maps (stage 2). Generated by tools/clones/gen_sql.py from the client's own Map.dbc and
-- MapDifficulty.dbc, the same rows as client_patch/patch-T.MPQ (rows checksum b53927e37d433316).
-- Do not edit by hand: change tools/clones/clones.json and regenerate both.
--
-- Reserved IDs only (maps 900-949, MapDifficulty 754+). A clone's map_dbc, mapdifficulty_dbc and
-- instance_template rows are always installed together. The rows are inert: nothing enters a clone unless
-- mod-atlas sends a run there (Atlas.Clones.Enable and the player's opt-in). Uninstall:
-- data/sql/uninstall/atlas_clones_uninstall.sql.

CREATE TABLE IF NOT EXISTS `atlas_map_source` (
    `clone_map`  SMALLINT UNSIGNED NOT NULL COMMENT 'clone map ID (900-949)',
    `source_map` SMALLINT UNSIGNED NOT NULL COMMENT 'the stock map whose terrain it reuses',
    `enabled`    TINYINT UNSIGNED  NOT NULL DEFAULT 0 COMMENT 'runs may open in it',
    `name`       VARCHAR(100)      NOT NULL DEFAULT '',
    PRIMARY KEY (`clone_map`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='mod-atlas: clone map registry';

-- Remove every reserved clone row first, so a clone dropped from clones.json disappears too.
DELETE FROM `atlas_map_source` WHERE `clone_map` BETWEEN 900 AND 949;
DELETE FROM `instance_template` WHERE `map` BETWEEN 900 AND 949;
DELETE FROM `mapdifficulty_dbc` WHERE `MapID` BETWEEN 900 AND 949;
DELETE FROM `map_dbc` WHERE `ID` BETWEEN 900 AND 949;
DELETE FROM `mapdifficulty_dbc` WHERE `ID` IN (754);

